const cfg = $('Configure MCP Endpoints & Pinned Hashes').first()?.json || {};
const alertOnCautionOnly = cfg.alertOnCautionOnly !== false;
const alerts = [];

for (const item of $input.all()) {
  const row = item.json;
  if (!row || row.status !== 'audited') continue;

  const criticalCount = row.findingsCount?.critical ?? 0;
  const highCount = row.findingsCount?.high ?? 0;
  const hasCriticalRisk = row.verdict === 'DANGEROUS' || row.rugPullDriftDetected === true || criticalCount > 0;
  const hasCautionRisk = row.verdict === 'CAUTION' || highCount > 0;

  if (!hasCriticalRisk && !(alertOnCautionOnly && hasCautionRisk)) continue;

  const findings = Array.isArray(row.findings) ? row.findings : [];
  alerts.push({
    json: {
      target: row.target,
      grade: row.grade,
      verdict: row.verdict,
      riskScore: row.riskScore ?? 0,
      toolCount: row.toolCount ?? 0,
      rugPullDriftDetected: Boolean(row.rugPullDriftDetected),
      manifestHashSha256: row.manifestHashSha256 || null,
      baselineHashProvided: row.baselineHashProvided || null,
      criticalFindings: criticalCount,
      highFindings: highCount,
      topRuleIds: findings.slice(0, 5).map((f) => f.ruleId).join(', '),
      alertSummary: `[${row.verdict}] ${row.target} (Grade ${row.grade}, risk ${row.riskScore ?? 0}, drift=${Boolean(row.rugPullDriftDetected)}): ${findings.map((f) => f.ruleId).join(', ') || 'High-risk findings'}`,
      auditedAt: row.auditedAt || null
    }
  });
}

return alerts;
